#include <WiFi.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// До 10 точек доступа — железный лимит ESP32
const char* NAMES[] = {
  "ТЦК Бусик 1",
  "ТЦК Бусик 2",
  "ТЦК Бусик 3",
  "ТЦК Бусик 4",
  "ТЦК Бусик 5",
  "ТЦК Бусик 6",
  "ТЦК Бусик 7",
  "ТЦК Бусик 8",
  "ТЦК Бусик 9",
  "ТЦК Бусик 10"
};

const int COUNT = sizeof(NAMES) / sizeof(NAMES[0]);

void setup() {
  WiFi.mode(WIFI_AP);
  for (int i = 0; i < COUNT; i++) {
    bool ok = WiFi.softAP(NAMES[i], "", i + 1);  // каналы 1..10
    Serial.printf("%s: %s\n", NAMES[i], ok ? "запущена" : "ошибка");
  }
}

void loop() {
}
